#!/bin/bash

################################################################################################
### sbatch configuration parameters must start with #SBATCH and must precede any other commands.
### To ignore, just add another # - like so: ##SBATCH
################################################################################################

#SBATCH --partition main                        ### specify partition name where to run a job. main: all nodes; gtx1080: 1080 gpu card nodes; rtx2080: 2080 nodes; teslap100: p100 nodes; titanrtx: titan nodes
#SBATCH --time 0-23:00:00                       ### limit the time of job running. Make sure it is not greater than the partition time limit!! Format: D-H:MM:SS
#SBATCH --job-name deepsic                      ### name of the job
#SBATCH --array=0-103                 ### run parallel 5 times
#SBATCH --output logs/job-%A_%a.out                     ### output log for running job - %A_%a for array job ID and task index (matches squeue's display)
#SBATCH --nodes=1                               ### single node per array task
#SBATCH --ntasks=1                              ### single task per array element
#SBATCH --cpus-per-task=1                       ### job is single-threaded; requesting more cores wastes allocation (see Slurm serial-workload report)

# Note: the following 4 lines are commented out
##SBATCH --gpus=rtx_3090:1                      ### number of GPUs, allocating more than 1 requires IT team's permission. Example to request 3090 gpu: #SBATCH --gpus=rtx_3090:1
##SBATCH --mail-user=egero@post.bgu.ac.il       ### user's email for sending job status messages
##SBATCH --mail-type=ALL                        ### conditions for sending the email. ALL,BEGIN,END,FAIL, REQUEU, NONE
#SBATCH --mem=6G                                ### ammount of RAM memory, allocating more than 60G requires IT team's permission

