cd /home/egero/Projects/DeepOFDM
# default (no flag, or --train): evaluate; --track: ekf; --drift: run_multiple_eval
if [[ "$1" == "--drift" ]]; then
  /usr/bin/time -v python -m python_code.run_multiple_eval --config config_files/$config_file
elif [[ "$1" == "--track" ]]; then
  /usr/bin/time -v python -m python_code.ekf --config config_files/$config_file
elif [[ -z "$1" || "$1" == "--train" ]]; then
  /usr/bin/time -v python -m python_code.evaluate --config config_files/$config_file
else
  echo "ERROR: unknown option '$1' (use --track, --drift, --train or nothing)" >&2
  exit 1
fi

